description:
Objective:
Add the core configuration loader: typed `LoreweaverConfig`, `loadConfig(env)`
with validation, and `ConfigError`. Export from the core barrel.

Files:
- Create: `packages/core/src/config.ts`
- Modify: `packages/core/src/index.ts`
- Test:   `packages/core/test/config.test.ts`

Steps:

1. Write the failing test `packages/core/test/config.test.ts`:
```ts
import { describe, expect, it } from 'vitest';
import { ConfigError, loadConfig } from '../src/config.js';

describe('loadConfig', () => {
  it('returns a valid config from a complete env', () => {
    const cfg = loadConfig({
      LOREWEAVER_DB_PATH: './campaigns/x.db',
      LOREWEAVER_MODEL: 'claude-opus-4-7',
      ANTHROPIC_API_KEY: 'sk-test',
    });
    expect(cfg).toEqual({
      campaignDbPath: './campaigns/x.db',
      model: 'claude-opus-4-7',
      anthropicApiKey: 'sk-test',
    });
  });

  it('defaults the model when unset', () => {
    const cfg = loadConfig({
      LOREWEAVER_DB_PATH: './x.db',
      ANTHROPIC_API_KEY: 'sk-test',
    });
    expect(cfg.model).toBe('claude-opus-4-7');
  });

  it('throws ConfigError when LOREWEAVER_DB_PATH is missing', () => {
    expect(() => loadConfig({ ANTHROPIC_API_KEY: 'sk-test' })).toThrow(ConfigError);
  });

  it('throws ConfigError when ANTHROPIC_API_KEY is missing', () => {
    expect(() => loadConfig({ LOREWEAVER_DB_PATH: './x.db' })).toThrow(ConfigError);
  });
});
```

2. Run the test to verify it FAILS.
   Command: `npx vitest run packages/core/test/config.test.ts`
   Expected: FAIL — cannot resolve `../src/config.js` (module does not exist).

3. Create `packages/core/src/config.ts`:
```ts
export interface LoreweaverConfig {
  campaignDbPath: string;
  model: string;
  anthropicApiKey: string;
}

export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

const DEFAULT_MODEL = 'claude-opus-4-7';

export function loadConfig(
  env: Record<string, string | undefined> = process.env,
): LoreweaverConfig {
  const campaignDbPath = env.LOREWEAVER_DB_PATH?.trim();
  const anthropicApiKey = env.ANTHROPIC_API_KEY?.trim();
  const model = env.LOREWEAVER_MODEL?.trim() || DEFAULT_MODEL;

  if (!campaignDbPath) {
    throw new ConfigError('LOREWEAVER_DB_PATH is required');
  }
  if (!anthropicApiKey) {
    throw new ConfigError('ANTHROPIC_API_KEY is required');
  }
  return { campaignDbPath, model, anthropicApiKey };
}
```

4. Add to `packages/core/src/index.ts` (append):
```ts
export { loadConfig, ConfigError } from './config.js';
export type { LoreweaverConfig } from './config.js';
```

5. Run the test to verify it PASSES.
   Command: `npx vitest run packages/core/test/config.test.ts`
   Expected: 4 passed.

6. Typecheck.
   Command: `npm run build`
   Expected: exit 0.

7. Commit.
   Command: `git add -A && git commit -m "feat(e0): config loader with validation"`
